"""Cancel bookkeeping shared by the skill executor and the A2A cancel handler.

Dropping path frames from the stack records the same events wherever it
happens: ``OrderedBlockCancelled`` for each ordered-block frame, then
``SkillCancelled`` once per skill. The LLM ``cancel`` tool and an orchestrator
``tasks/cancel`` differ in which frames they drop and what happens next, not
in how a dropped frame is recorded, so that part lives here.
"""

from __future__ import annotations

from typing import List, Optional, Sequence

from rasa.dialogue_understanding.stack.frames.flow_stack_frame import UserFlowStackFrame
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.orchestration.skill_utils import owning_skill_id_for_frame
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    entry_target_id_for_skill,
    skill_has_prose,
)
from rasa.mantle.skills.stack_frame_helpers import (
    MantlePathFrame,
    catalog_step_id,
    target_id_for_frame,
)
from rasa.shared.core.events import Event, OrderedBlockCancelled, SkillCancelled


def authored_block_id_for_frame(
    catalog: SkillCatalog, frame: MantlePathFrame
) -> Optional[str]:
    """Return the authored ordered-block id for *frame*, if it is a block.

    Live ordered-block frames store ``block_id``. ``UserFlowStackFrame`` is
    read-only for now; when one is still on the stack, resolve its block id
    through the catalog from ``flow_id``.
    """
    if isinstance(frame, OrderedBlockStackFrame):
        return frame.block_id
    if isinstance(frame, SkillStackFrame):
        return None
    return catalog.ordered_block_id_for_target(frame.flow_id)


def is_skill_level_target(
    catalog: SkillCatalog, target_id: str, skill_id: Optional[str]
) -> bool:
    """Return whether *target_id* is leaving or representing the skill itself.

    Prose and standalone skills are skill-level. A blocks-only ordered block is
    skill-level only when it is that skill's entry block, so completing a block
    reached by ``call:`` returns to the entry. An ordered block of a skill with
    prose is not skill-level.
    """
    if skill_id is None:
        return False

    target = catalog.resolve_activation_target(target_id)
    if target is None:
        # Missing ids must not look like routable entries.
        return False

    if target.routable:
        skill = catalog.skill_by_id(skill_id)
        is_block = catalog.ordered_block_id_for_target(target_id) is not None
        if skill is not None and is_block:
            if skill_has_prose(skill):
                return False
            # Only the entry leaves a blocks-only skill. A called block
            # returns to that entry.
            return target_id == entry_target_id_for_skill(skill)
        return True

    skill = catalog.owning_skill_for_target_id(target_id)
    if skill is None or skill_has_prose(skill):
        return False
    return target_id == entry_target_id_for_skill(skill)


def cancelled_events_for_frames(
    catalog: SkillCatalog,
    frames: Sequence[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame],
) -> List[Event]:
    """Return the cancel events for dropping *frames*.

    Writes ``OrderedBlockCancelled`` per block frame and ``SkillCancelled`` once
    per skill. Pass *frames* from the top of the stack down so the skill event
    carries the step the user was on.
    """
    events: List[Event] = []
    emitted_skill_ids: set[str] = set()
    for frame in frames:
        compiled_flow_id = target_id_for_frame(frame)
        step_id = catalog_step_id(frame)
        skill_id = owning_skill_id_for_frame(catalog, frame)
        cancelled_block_id = authored_block_id_for_frame(catalog, frame)
        # Block ends before the skill wrapper: emit OrderedBlockCancelled
        # first, then SkillCancelled once per skill.
        if skill_id is not None and cancelled_block_id is not None:
            events.append(
                OrderedBlockCancelled(
                    skill_id=skill_id,
                    block_id=cancelled_block_id,
                    step_id=step_id,
                )
            )
        # The wrapper is the skill. Its id is not an activation target,
        # so the entry check misses it after a same-skill link.
        ends_blocks_only_skill = False
        if isinstance(frame, SkillStackFrame) and skill_id is not None:
            skill = catalog.skill_by_id(skill_id)
            ends_blocks_only_skill = skill is not None and not skill_has_prose(skill)
        if (
            skill_id is not None
            and skill_id not in emitted_skill_ids
            and (
                is_skill_level_target(catalog, compiled_flow_id, skill_id)
                or ends_blocks_only_skill
            )
        ):
            events.append(SkillCancelled(skill_id=skill_id, step_id=step_id))
            emitted_skill_ids.add(skill_id)
    return events
